extends CharacterBody3D
class_name PlayerController

signal interaction_target_changed(target: Interactable)
signal entered_vehicle(vehicle: Node)

@export var walk_speed := 5.5
@export var run_speed := 9.0
@export var acceleration := 18.0
@export var rotation_speed := 12.0
@export var gravity := 18.0
@export var interaction_distance := 3.0

@onready var camera_pivot: Node3D = $CameraPivot
@onready var camera: Camera3D = $CameraPivot/Camera3D

var interaction_target: Interactable
var camera_yaw := 0.0
var camera_pitch := -0.2
var input_enabled := true
var mobile_input_router = null
var mobile_camera_sensitivity := 0.0042

func configure_mobile_input(router) -> void:
    mobile_input_router = router

func _physics_process(delta: float) -> void:
    if not input_enabled:
        velocity = Vector3.ZERO
        move_and_slide()
        return

    var input2 := Input.get_vector("move_left", "move_right", "move_forward", "move_back")
    if mobile_input_router != null:
        var touch_input: Vector2 = mobile_input_router.movement_vector()
        if touch_input.length() > input2.length():
            input2 = touch_input
    var basis := Basis(Vector3.UP, camera_yaw)
    var dir := (basis * Vector3(input2.x, 0.0, input2.y)).normalized()

    var sprint_active := Input.is_action_pressed("sprint")
    if mobile_input_router != null:
        sprint_active = sprint_active or mobile_input_router.wants_sprint()
    var speed := run_speed if sprint_active else walk_speed
    var target := dir * speed
    velocity.x = move_toward(velocity.x, target.x, acceleration * delta)
    velocity.z = move_toward(velocity.z, target.z, acceleration * delta)

    if not is_on_floor():
        velocity.y -= gravity * delta
    else:
        velocity.y = -0.1

    if dir.length_squared() > 0.01:
        var target_yaw := atan2(dir.x, dir.z)
        rotation.y = lerp_angle(rotation.y, target_yaw, rotation_speed * delta)

    move_and_slide()
    _find_interaction_target()

    if Input.is_action_just_pressed("interact") and interaction_target:
        interaction_target.interact(self)


func apply_mobile_camera_drag(delta: Vector2) -> void:
    camera_yaw -= delta.x * mobile_camera_sensitivity
    camera_pitch = clampf(
        camera_pitch - delta.y * mobile_camera_sensitivity,
        -0.65,
        0.35
    )
    camera_pivot.rotation = Vector3(camera_pitch, camera_yaw, 0.0)

func set_mobile_camera_sensitivity(value: float) -> void:
    mobile_camera_sensitivity = clampf(value, 0.001, 0.02)

func _unhandled_input(event: InputEvent) -> void:
    if event is InputEventMouseMotion and Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:
        camera_yaw -= event.relative.x * 0.003
        camera_pitch = clampf(camera_pitch - event.relative.y * 0.0025, -0.65, 0.35)
        camera_pivot.rotation = Vector3(camera_pitch, camera_yaw, 0.0)
    if event.is_action_pressed("ui_cancel"):
        Input.mouse_mode = Input.MOUSE_MODE_VISIBLE
    if event is InputEventMouseButton and event.pressed:
        Input.mouse_mode = Input.MOUSE_MODE_CAPTURED

func _find_interaction_target() -> void:
    var best: Interactable = null
    var best_dist := interaction_distance
    for node in get_tree().get_nodes_in_group("interactable"):
        if node is Interactable and node.enabled:
            var d := global_position.distance_to(node.global_position)
            if d < best_dist:
                best_dist = d
                best = node
    if best != interaction_target:
        interaction_target = best
        interaction_target_changed.emit(best)

func set_control_enabled(value: bool) -> void:
    input_enabled = value


func request_interact() -> void:
    if interaction_target != null and interaction_target.can_interact(self):
        interaction_target.interact(self)


func serialize_runtime() -> Dictionary:
    return {
        "position": [global_position.x, global_position.y, global_position.z],
        "rotation": [global_rotation.x, global_rotation.y, global_rotation.z],
        "camera_yaw": camera_yaw,
        "camera_pitch": camera_pitch
    }

func restore_runtime(data: Dictionary) -> void:
    var position_value = data.get("position", [])
    if _is_vec3_array(position_value):
        global_position = _safe_vec3(position_value, global_position, 10000.0)

    var rotation_value = data.get("rotation", [])
    if _is_vec3_array(rotation_value):
        global_rotation = _safe_vec3(rotation_value, global_rotation, TAU * 8.0)

    camera_yaw = clampf(float(data.get("camera_yaw", camera_yaw)), -TAU * 8.0, TAU * 8.0)
    camera_pitch = clampf(float(data.get("camera_pitch", camera_pitch)), -0.65, 0.35)
    if camera_pivot:
        camera_pivot.rotation = Vector3(camera_pitch, camera_yaw, 0.0)
    velocity = Vector3.ZERO

func _is_vec3_array(value) -> bool:
    return typeof(value) == TYPE_ARRAY and value.size() == 3

func _safe_vec3(value: Array, fallback: Vector3, limit: float) -> Vector3:
    if value.size() != 3:
        return fallback
    var x := float(value[0])
    var y := float(value[1])
    var z := float(value[2])
    if is_nan(x) or is_nan(y) or is_nan(z) or is_inf(x) or is_inf(y) or is_inf(z):
        return fallback
    return Vector3(
        clampf(x, -limit, limit),
        clampf(y, -limit, limit),
        clampf(z, -limit, limit)
    )

extends Node
class_name PlayerSafetySystem

signal recovery_performed(reason: String, recovered_vehicle: bool)

@export var sample_interval_seconds := 0.5
@export var void_y := -12.0
@export var max_world_radius := 2200.0

var player: PlayerController
var spawn_transform := Transform3D.IDENTITY
var last_safe_player_transform := Transform3D.IDENTITY
var last_safe_vehicle_transforms: Dictionary = {}
var elapsed := 0.0

func configure(value: PlayerController) -> void:
    player = value
    spawn_transform = player.global_transform
    last_safe_player_transform = spawn_transform
    process_mode = Node.PROCESS_MODE_ALWAYS

func _process(delta: float) -> void:
    if player == null:
        return
    elapsed += delta
    if elapsed < sample_interval_seconds:
        return
    elapsed = 0.0
    if _recover_invalid_active_state():
        return
    _capture_safe_checkpoint()

func force_unstuck() -> bool:
    if player == null:
        return false
    var active := _active_vehicle()
    if active != null:
        _recover_vehicle(active, "manual_unstuck")
        return true
    _recover_player("manual_unstuck")
    return true

func _recover_invalid_active_state() -> bool:
    var active := _active_vehicle()
    if active != null:
        if not _transform_is_safe(active.global_transform):
            _recover_vehicle(active, _reason_for_position(active.global_position))
            return true
        return false

    if not _transform_is_safe(player.global_transform):
        _recover_player(_reason_for_position(player.global_position))
        return true
    return false

func _capture_safe_checkpoint() -> void:
    var active := _active_vehicle()
    if active != null:
        if active.is_on_floor() and _transform_is_safe(active.global_transform):
            last_safe_vehicle_transforms[active.vehicle_id] = active.global_transform
        return
    if player.visible and player.input_enabled and player.is_on_floor() and _transform_is_safe(player.global_transform):
        last_safe_player_transform = player.global_transform

func _recover_player(reason: String) -> void:
    var target := last_safe_player_transform if _transform_is_safe(last_safe_player_transform) else spawn_transform
    player.global_transform = target
    player.velocity = Vector3.ZERO
    player.visible = true
    player.set_control_enabled(true)
    GameState.current_vehicle_id = ""
    _record_recovery(reason, false)

func _recover_vehicle(vehicle: ArcadeVehicle, reason: String) -> void:
    var target: Transform3D = last_safe_vehicle_transforms.get(vehicle.vehicle_id, Transform3D.IDENTITY)
    if not _transform_is_safe(target):
        target = Transform3D(Basis.IDENTITY, spawn_transform.origin + Vector3(4.0, 1.0, 0.0))
    vehicle.global_transform = target
    vehicle.speed = 0.0
    vehicle.velocity = Vector3.ZERO
    if vehicle.driver == player:
        player.global_position = vehicle.seat.global_position
        player.global_rotation.y = vehicle.global_rotation.y
        player.velocity = Vector3.ZERO
    _record_recovery(reason, true)

func _active_vehicle() -> ArcadeVehicle:
    if GameState.current_vehicle_id.is_empty():
        return null
    for node in get_tree().get_nodes_in_group("runtime_vehicle"):
        if node is ArcadeVehicle and node.vehicle_id == GameState.current_vehicle_id:
            return node as ArcadeVehicle
    return null

func _transform_is_safe(value: Transform3D) -> bool:
    if not _vector_is_finite(value.origin):
        return false
    if value.origin.y < void_y:
        return false
    if absf(value.origin.x) > max_world_radius or absf(value.origin.z) > max_world_radius:
        return false
    var basis_values := [
        value.basis.x.x, value.basis.x.y, value.basis.x.z,
        value.basis.y.x, value.basis.y.y, value.basis.y.z,
        value.basis.z.x, value.basis.z.y, value.basis.z.z
    ]
    for component in basis_values:
        if is_nan(float(component)) or is_inf(float(component)):
            return false
    return true

func _vector_is_finite(value: Vector3) -> bool:
    return not (
        is_nan(value.x) or is_nan(value.y) or is_nan(value.z)
        or is_inf(value.x) or is_inf(value.y) or is_inf(value.z)
    )

func _reason_for_position(position: Vector3) -> String:
    if not _vector_is_finite(position):
        return "non_finite_transform"
    if position.y < void_y:
        return "fell_into_void"
    if absf(position.x) > max_world_radius or absf(position.z) > max_world_radius:
        return "outside_world_bounds"
    return "invalid_transform"

func _record_recovery(reason: String, recovered_vehicle: bool) -> void:
    RuntimeDiagnostics.record_event("player_safety_recovery", {
        "reason": reason,
        "vehicle": recovered_vehicle,
        "vehicle_id": GameState.current_vehicle_id
    })
    RuntimeDiagnostics.write_health_snapshot("player_safety_recovery")
    recovery_performed.emit(reason, recovered_vehicle)

extends Node
class_name RestSystem

signal rested(kind: String, energy_gain: float)
signal rest_rejected(kind: String, reason: String)

const CONFIG_PATH := "res://data/rest/rest_config.json"

var clock = null
var config: Dictionary = {}

func _ready() -> void:
    _load_config()

func configure(world_clock) -> void:
    clock = world_clock

func can_rest(kind: String) -> bool:
    if not config.has(kind):
        return false
    var cfg: Dictionary = config[kind]
    var water_cost := float(cfg.get("water_cost", 0.0))
    return GameState.water >= water_cost

func rest(kind: String) -> bool:
    if not config.has(kind):
        rest_rejected.emit(kind, "unknown_rest_kind")
        return false

    if not can_rest(kind):
        rest_rejected.emit(kind, "not_enough_water")
        return false

    var cfg: Dictionary = config[kind]
    var gain := float(cfg.get("energy_gain", 0.0))
    var water_cost := float(cfg.get("water_cost", 0.0))
    var minutes := int(cfg.get("duration_game_minutes", 0))

    GameState.set_stat("water", GameState.water - water_cost)
    GameState.set_stat("energy", GameState.energy + gain)

    if clock != null:
        clock.skip_minutes(minutes)

    rested.emit(kind, gain)
    return true

func _load_config() -> void:
    if not FileAccess.file_exists(CONFIG_PATH):
        return

    var f := FileAccess.open(CONFIG_PATH, FileAccess.READ)
    if f == null:
        return

    var parsed = JSON.parse_string(f.get_as_text())
    if typeof(parsed) == TYPE_DICTIONARY:
        config = parsed
